  content = $json${"level_id":"6.3","badge_name":"যন্ত্র গুরু","level_title":"ফিউজ: নীরব প্রহরী ও তারের সঠিক হিসাব","mission_briefing":"লাইন বা ট্রান্সফরমারকে বড় বিপদের হাত থেকে বাঁচাতে যে যন্ত্রটি নিজের জীবন উৎসর্গ করে দেয়, সে হলো আমাদের ফিউজ। আপনি হয়তো অন্যান্য জায়গায় ড্রপ আউট (DO) ফিউজ দেখেছেন, কিন্তু পশ্চিমবঙ্গে আমাদের ১১ কেভি ডিস্ট্রিবিউশন সিস্টেমে সুরক্ষার জন্য এক বিশেষ ব্যবস্থা ব্যবহার করা হয়। এই লেভেলে আমরা পশ্চিমবঙ্গের আসল প্রহরী—হর্ন গ্যাপ (HG) ফিউজ সম্পর্কে জানব, HRC ও কিট-ক্যাট ফিউজের কাজের ধরন বুঝব এবং সবচেয়ে জরুরি—মাঠে ফিউজ তার নির্বাচন, গেজ (SWG) পরিমাপ ও ফিউজ বাঁধার খাঁটি বৈজ্ঞানিক নিয়ম সম্পর্কে জানব, যাতে কোনো 'জুগাড়' কাজের জন্য আমাদের সাধের ট্রান্সফরমারটি পুড়ে ছাই না হয়ে যায়!","sections":[{"title":"নীরব প্রহরীদের চেনা ও তারের সঠিক হিসাব","points":[{"item_name":"১. হর্ন গ্যাপ (HG) ফিউজ: পশ্চিমবঙ্গের ১১ কেভি লাইনের আসল প্রহরী","specifications":"• পশ্চিমবঙ্গের নিয়ম: পশ্চিমবঙ্গে (WBSEDCL) ১১ কেভি ডিস্ট্রিবিউশন ট্রান্সফরমার (DTR) বা এবি সুইচের (Isolator) সাথে সাধারণত ড্রপ আউট (DO) ফিউজ ব্যবহার করা হয় না। তার বদলে পোলের ওপর অত্যন্ত সাশ্রয়ী ও নির্ভরযোগ্য 'হর্ন গ্যাপ' (HG) ফিউজ এবং সাধারণ ফিউজ তারের সেটআপ ব্যবহার করা হয়।\n• গঠন: এতে চিনেমাটির ইনসুলেটরের ওপর দুটি শিংয়ের মতো বাঁকানো তামার দণ্ড বা আর্কিং হর্ন (Arcing Horn) থাকে। এই দুটি হর্নের মাঝে সাধারণ ফিউজ তার (Tinned Copper Wire) টানটান করে বেঁধে দেওয়া হয়।\n• আর্ক নেভানোর কৌশল: শর্ট সার্কিট হলে ফিউজ তারটি গলে যায়। তার গলার সময় যে তীব্র বৈদ্যুতিক আর্ক (ঝিলিক) তৈরি হয়, তা হর্নের বাঁকানো আকৃতির কারণে এবং গরম বাতাস ওপরের দিকে ওঠার ফলে প্রসারিত (Elongate) হয়ে বাতাসে নিজে থেকেই নিভে যায়।\n• ফিউজ তারের রেটিং: ট্রান্সফরমারের ক্ষমতা অনুযায়ী সঠিক রেটিংয়ের ফিউজ তার ব্যবহার করতে হবে। ((যেমন, ১১ কেভি সাইডে ২৫ kVA ট্রান্সফরমারের জন্য ২A বা ৩A, ৬৩ kVA-এর জন্য ৫A এবং ১০০ kVA-এর জন্য ৮A বা ১০A ফিউজ তার ব্যবহার করা উচিত। ভুল করে বেশি রেটিংয়ের তার দিলে ফল্টের সময় ফিউজ গলবে না, ট্রান্সফরমারটি পুড়ে যাবে!|সঠিক ফিউজ তারের রেটিং))","importance":"হর্ন গ্যাপ ফিউজ অত্যন্ত সাশ্রয়ী, মজবুত এবং খোলা বাতাসে কোনো জটিল মেকানিজম ছাড়াই নিরাপদে আর্ক নেভাতে পারে, যা আমাদের গ্রামীণ ও শহরের ওভারহেড লাইনে সবচেয়ে বেশি সফল।","image_name":"/images/loader/fuse63_hg.webp","image_caption":"হর্ন গ্যাপ (HG) ফিউজ · ১১ kV ওভারহেড"},{"item_name":"২. এইচআরসি (HRC) ফিউজ: এলটি বক্সের বিশ্বস্ত প্রহরী","specifications":"• গঠন: এটি একটি সম্পূর্ণ সিল করা সিরামিক বা চিনেমাটির সিলিন্ডার, যার ভেতরে রুপো বা তামার পাতলা ফিউজ এলিমেন্ট থাকে এবং চারপাশ কোয়ার্টজ বালু (Quartz Sand) দিয়ে ঠাসা থাকে।\n• ব্যবহার: ডিস্ট্রিবিউশন ট্রান্সফরমারের পোলে থাকা এলটি ডিস্ট্রিবিউশন বক্স (LT DB), ফিডার পিলার এবং বড় সাবস্টেশন প্যানেলে এটি ব্যবহৃত হয়।\n• বৈশিষ্ট্য: এর ফল্ট কারেন্ট আটকানোর ক্ষমতা (Rupturing Capacity) অত্যন্ত বেশি। ফল্টের সময় ভেতরের তারটি গলে বাষ্প হয়ে যায় এবং কোয়ার্টজ বালু সেই তীব্র আগুন বা আর্ককে বাইরে ছড়াতে না দিয়ে ভেতরেই শুষে নেয়। ((HRC ফিউজ ওড়ার সময় কোনো শব্দ বা বিস্ফোরণ ঘটে না, তাই এটি অত্যন্ত নিরাপদ। অনেক ফিউজের গায়ে ছোট লাল বা রঙিন ইন্ডিকেটর ডট থাকে, যা ফিউজ উড়ে গেলে ছিটকে বেরিয়ে যায় বা কালো হয়ে যায়।|কীভাবে বুঝবেন ফিউজ উড়েছে?))","importance":"যেখানে ফল্ট কারেন্টের মাত্রা খুব বেশি এবং বিস্ফোরণ বা আগুনের ঝুঁকি থাকে, সেখানে HRC ফিউজ ব্যবহার করা বাধ্যতামূলক। এটি কিট-ক্যাটের চেয়ে অনেক বেশি নির্ভরযোগ্য।","image_name":"/images/loader/fuse63_hrc.webp","image_caption":"HRC ফিউজ · এলটি ডিস্ট্রিবিউশন বক্স"},{"item_name":"৩. কিট-ক্যাট ফিউজ: পুরনো দিনের সৈনিক","specifications":"• গঠন: এটি পোর্সেলিন বা চিনেমাটির তৈরি দুটি অংশ নিয়ে গঠিত—একটি স্থায়ী বেস এবং একটি খোলা-নেওয়া যায় এমন ফিউজ ক্যারিয়ার বা কিট-ক্যাট।\n• ব্যবহার: পুরনো দিনের এলটি বক্স, গ্রামীণ ডিস্ট্রিবিউশন বোর্ড এবং গ্রাহকের মিটার বোর্ডে এটি দেখা যায়।\n• সীমাবদ্ধতা: এর ব্রেকিং ক্যাপাসিটি খুব কম, এটি খোলা পরিবেশে আর্ক তৈরি করে এবং এর সুরক্ষার কোনো নিশ্চয়তা নেই কারণ ব্যবহারকারী যেকোনো মোটা তার ব্যবহার করতে পারেন।","importance":"কিট-ক্যাট ফিউজ সস্তা এবং বারবার তার বেঁধে ব্যবহার করা যায় ঠিকই, কিন্তু এর ব্রেকিং ক্যাপাসিটি কম এবং খোলা বাতাসে আর্ক তৈরি হওয়ায় এটি আধুনিক সিস্টেমে আর রিকমেন্ড করা হয় না।","image_name":"/images/loader/fuse63_kitkat.webp","image_caption":"কিট-ক্যাট ফিউজ · পুরনো ধরন"},{"item_name":"৪. ফিউজ তার নির্বাচন ও সাইজ পরিমাপ (SWG)","specifications":"• ফিউজ তারের উপাদান: ফিউজ তার হিসেবে সবসময় স্ট্যান্ডার্ড টিন-লেপযুক্ত তামার তার (Tinned Copper Wire) ব্যবহার করা উচিত। তামার ওপর টিনের প্রলেপ থাকলে তা তামাকে বাতাসে অক্সিডাইজড বা মরিচা পড়া থেকে বাঁচায় এবং এর গলনাঙ্ককে স্থিতিশীল রাখে।\n• সাইজ পরিমাপ (SWG): ফিউজ তারের মোটা বা চিকন হওয়া মাপা হয় SWG (Standard Wire Gauge) নম্বর দিয়ে। মনে রাখবেন, গেজ নম্বর যত বাড়ে, তার তত চিকন হয় (যেমন ২৯ SWG); আর গেজ নম্বর যত কমে, তার তত মোটা হয় (যেমন ১২ SWG)। মাঠে কাজ করার সময় পকেট 'ওয়্যার গেজ' টুল বা মাইক্রোমিটার দিয়ে তারের ব্যাস মাপা যায়।\n• পশ্চিমবঙ্গে ডিস্ট্রিবিউশন লাইনে ব্যবহৃত স্ট্যান্ডার্ড ফিউজ তারের তালিকা:\n  - ১৬ এম্পিয়ার (গ্রাহক মিটার): ২৯ SWG (ব্যাস ০.৩৪৮ মিমি)\n  - ৩২ এম্পিয়ার (এলটি ডিস্ট্রিবিউশন): ২২ SWG (ব্যাস ০.৭১১ মিমি)\n  - ৬৩ এম্পিয়ার (ছোট DTR এলটি বক্স): ২০ SWG (ব্যাস ০.৯১৪ মিমি)\n  - ১০০ এম্পিয়ার (মাঝারি DTR এলটি বক্স): ১৮ SWG (ব্যাস ১.২১৯ মিমি)\n  - ২০০ এম্পিয়ার (বড় DTR এলটি বক্স): ১৪ SWG (ব্যাস ২.০৩২ মিমি)\n  - ৩০০ এম্পিয়ার (ফিডার পিলার): ১২ SWG (ব্যাস ২.৬৪০ মিমি)\n• মাল্টি-স্ট্র্যান্ড তারের নিয়ম: যদি সঠিক গেজের একক তার না থাকে, তবে চিকন তারের কয়েকটি সুতো (Strands) একসাথে পেঁচিয়ে প্রয়োজনীয় রেটিং তৈরি করা যায়। কিন্তু এটি করার সময় হিসাব খুব নিখুঁত হতে হবে। যেমন, দুটি ২২ SWG তার একসাথে পেঁচালে তা প্রায় ৬৩ এম্পিয়ারের কাজ করতে পারে। কিন্তু আন্দাজে পেঁচানো যাবে না। ((ফিউজ তারের ব্যাস ও গেজ সঠিকভাবে পরিমাপ করার জন্য সবসময় একটি স্ট্যান্ডার্ড মেটাল ওয়্যার গেজ প্লেট ব্যবহার করুন। তারের ইনসুলেশন ছাড়িয়ে খালি কন্ডাক্টরটি গেজের খাঁজে প্রবেশ করিয়ে সঠিক নম্বরটি দেখে নিন।|কীভাবে গেজ পরিমাপ করবেন?))","importance":"সঠিক ফিউজ তার নির্বাচন এবং গেজ পরিমাপ করাটা সিস্টেমের সুরক্ষা ও নির্ভরযোগ্যতার জন্য অত্যন্ত জরুরি। আন্দাজে মোটা তার লাগালে ফিউজ তারের আসল উদ্দেশ্যই নষ্ট হয়ে যায়।","image_name":"/images/loader/fuse63_wire_selection.webp","image_caption":"ওয়্যার গেজ প্লেট · SWG পরিমাপ"},{"item_name":"৫. মাঠের মারাত্মক ভুল: অ্যালুমিনিয়াম বা জিআই তারের জুগাড়","specifications":"• জুগাড়ের বিপদ: মাঠে কাজ করার সময় সঠিক ফিউজ তার না থাকলে অনেকেই হাতের কাছে থাকা ACSR কন্ডাক্টরের অ্যালুমিনিয়ামের সুতো (Strand) বা জিআই বাইন্ডিং তার (GI Binding Wire) কিট-ক্যাটে পেঁচিয়ে দেন। এটি একটি চরম অপরাধ!\n• গলনাঙ্কের পার্থক্য: লোহার (GI) গলনাঙ্ক প্রায় ১৫৩৫° সেলসিয়াস এবং অ্যালুমিনিয়ামের ৬৬০° সেলসিয়াস, যেখানে তামার ১০৮৫° সেলসিয়াস। লোহার রেজিস্ট্যান্স বেশি হওয়ায় এটি সহজে গলতে চায় না।\n• পরিণতি: অ্যালুমিনিয়াম বা জিআই তারের কারেন্ট সহ্য করার ক্ষমতা অনেক বেশি হওয়ায় লাইনে শর্ট সার্কিট হলেও এই জুগাড় তার গলে না। ফলে পুরো ফল্ট কারেন্ট সরাসরি ট্রান্সফরমারে আঘাত করে এবং সাধের ট্রান্সফরমারটি পুড়ে ছাই হয়ে যায়! ((অ্যালুমিনিয়াম তার বাতাসে দ্রুত অক্সিডাইজড হয়ে যায়, ফলে কানেকশন ঢিলে হয়ে স্পার্কিং বাড়ে এবং ফিউজ হোল্ডারটি পুড়ে নষ্ট হয়ে যায়। তাই সবসময় শুধুমাত্র অনুমোদিত টিনড কপার ফিউজ তার ব্যবহার করুন।|অক্সিডেশনের বিপদ))","importance":"একটি সস্তা ফিউজ তারের বদলে ভুল তার ব্যবহার করার খেসারত দিতে হয় লক্ষাধিক টাকার ট্রান্সফরমার পুড়িয়ে এবং পুরো এলাকার বিদ্যুৎ বন্ধ করে।","image_name":"/images/loader/fuse63_jugaad.webp","image_caption":"অ্যালুমিনিয়াম/জিআই তার ✗ · টিনড কপার তার ✓"},{"item_name":"৬. ফিউজ বদলানোর সেফটি প্রোটোকল","specifications":"• লোড বিচ্ছিন্ন করুন: ফিউজ বদলানোর আগে গ্রাহক বা ফিডারের মেইন সুইচ বন্ধ করে লোড সম্পূর্ণ আইসোলেট করুন। অন-লোডে ফিউজ টানলে মারাত্মক আর্ক ফ্ল্যাশ হতে পারে।\n• পিপিই ব্যবহার: অবশ্যই এলটি/এইচটি ইনসুলেটেড হ্যান্ড গ্লাভস এবং সেফটি গগলস (চশমা) পরিধান করুন।\n• ফিউজ পুলার: HRC ফিউজ খোলার বা লাগানোর জন্য সবসময় ইনসুলেটেড ফিউজ পুলার (Fuse Puller) ব্যবহার করুন। প্লায়ার্স বা খালি হাত দিয়ে টানার চেষ্টা করবেন না।\n• ডিও ও এইচজি ফিউজ অপারেট: ডিও বা হর্ন গ্যাপ ফিউজ খোলার বা লাগানোর জন্য উপযুক্ত ইনসুলেটেড অপারেটিং রড (Operating Rod) ব্যবহার করুন এবং শুকনো ইনসুলেটিং ম্যাটের ওপর দাঁড়ান। ((ফিউজ ওড়ার আসল কারণ (যেমন লাইনে শর্ট সার্কিট বা ওভারলোড) না খুঁজে এবং তা মেরামত না করে কখনই বারবার ফিউজ চার্জ করবেন না। এতে ফল্ট আরও বড় আকার ধারণ করতে পারে।|চার্জ করার আগে সতর্ক হোন))","importance":"সুরক্ষা কোনো আপস মানে না। একটি ছোট ফিউজ বদলাতেও যদি আপনি নিয়ম না মানেন, তবে তা বড় দুর্ঘটনার কারণ হতে পারে।","image_name":"/images/loader/fuse63_safety.webp","image_caption":"ফিউজ পুলার · ইনসুলেটেড গ্লাভস"}]}],"image_suggestion":"পশ্চিমবঙ্গের ওভারহেড ডিস্ট্রিবিউশন লাইনের বাস্তবসম্মত চিত্র: ১. হর্ন গ্যাপ (HG) ফিউজ (পোল-মাউন্টেড, আর্কিং হর্নের মাঝে ফিউজ তার বাঁধা অবস্থা), ২. এইচআরসি ফিউজ (এলটি ডিস্ট্রিবিউশন বক্সের ভেতরে), ৩. কিট-ক্যাট ফিউজ (পোর্সেলিন বডি), ৪. ওয়্যার গেজ প্লেট দিয়ে ফিউজ তারের SWG পরিমাপ করার দৃশ্য, ৫. অ্যালুমিনিয়াম/জিআই জুগাড় তারের বিপদ (লাল ক্রস চিহ্ন), ৬. ফিউজ পুলার ও গ্লাভস পরিহিত লাইনম্যানের সুরক্ষিত অপারেশন।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. HRC ফিউজের ইন্ডিকেটর চেক: ফিউজটি ভালো আছে কি না তা দেখতে তার বডির ওপরে থাকা ছোট লাল বা হলুদ ডটটি খেয়াল করুন। ওটা উধাও বা কালো হয়ে গেলে বুঝবেন ফিউজ কেটে গেছে।","২. ফিউজের বৈষম্য (Discrimination): একটি আদর্শ সিস্টেমে বাড়ির ফিউজ বা MCB সবার আগে উড়বে, তারপর এলটি বক্সের ফিউজ, এবং সবশেষে ট্রান্সফরমারের এইচজি ফিউজ। যদি বাড়ির ফল্টে ট্রান্সফরমারের ফিউজ উড়ে যায়, তবে বুঝতে হবে ফিউজ কো-অর্ডিনেশন বা তারের সাইজ ভুল আছে।","৩. কপার স্ট্রিপ বা পাত ব্যবহার করবেন না: ফিডার পিলারের HRC ফিউজ কেটে গেলে অনেকেই সেখানে তামার পাত বা মোটা তার দিয়ে ডাইরেক্ট করে দেন। এটি চরম বিপজ্জনক! এর ফলে পুরো ফিডার পিলার বা ট্রান্সফরমারে আগুন লেগে যেতে পারে।","৪. স্পেয়ার ফিউজ মজুত রাখুন: পেট্রোলিং গাড়িতে বা নিজের টুলকিটে সবসময় সঠিক রেটিংয়ের কয়েকটি স্পেয়ার HRC ফিউজ এবং স্ট্যান্ডার্ড SWG তামা তারের রিল মজুত রাখুন, যাতে আপৎকালীন সময়ে জুগাড় করতে না হয়।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"কিট-ক্যাট ফিউজে যত মোটা তার বাঁধা যাবে, ফিউজ তত মজবুত হবে এবং বারবার ফিউজ ওড়ার ঝামেলা থাকবে না।","reality":"এটি সম্পূর্ণ ভুল এবং আত্মঘাতী ধারণা! ফিউজ তারের কাজই হলো লাইনে গড়বড় হলে নিজে গলে গিয়ে বাকি দামী সরঞ্জামকে বাঁচানো। তার অতিরিক্ত মোটা হলে ফিউজ উড়বে না, ফলে আপনার ঘরের দামি টিভি-ফ্রিজ বা লাইনের ট্রান্সফরমারটি পুড়ে ছাই হয়ে যাবে।"},{"myth":"ফিউজ ওড়ার পর হাতের কাছে ফিউজ তার না থাকলে সাময়িকভাবে অ্যালুমিনিয়াম কন্ডাক্টরের সুতো বা জিআই বাইন্ডিং তার ব্যবহার করা যেতে পারে।","reality":"একেবারেই না! অ্যালুমিনিয়াম বা লোহার গলনাঙ্ক অনেক বেশি হওয়ায় তারা ফল্ট কারেন্টেও গলে না। তাছাড়া অ্যালুমিনিয়ামের অক্সিডেশনের কারণে কানেকশন লুজ হয়ে স্পার্কিং এবং আগুন লাগার সম্ভাবনা থাকে। সাময়িক জুগাড়ও বড় বিপদের কারণ হতে পারে।"}],"image_name":"/images/loader/fuse63_myth.webp","image_caption":"সঠিক রেটিং তার ✓ · মোটা জুগাড় তার ✗"},"advanced_section":{"title":"এর পেছনের ইঞ্জিনিয়ারিং ফ্যাক্টস","facts":[{"title":"I²t ভ্যালু (Ampere-squared Seconds)","content":"এটি হলো ফিউজের তাপীয় শক্তি সহ্য করার সূচক। ফিউজ এলিমেন্টটি গলে সার্কিট সম্পূর্ণ বিচ্ছিন্ন করার আগে কতটা তাপশক্তি (Thermal Energy) প্রবাহিত হতে দেবে, তা এই I²t মান দিয়ে মাপা হয়। ফিউজের I²t মান সবসময় তার সুরক্ষিত ক্যাবল বা সরঞ্জামের চেয়ে কম হতে হবে, যাতে সরঞ্জাম গরম হওয়ার আগেই ফিউজ গলে যায়।"},{"title":"কারেন্ট লিমিটিং এফেক্ট (Current Limiting Effect)","content":"HRC ফিউজের একটি অসাধারণ ক্ষমতা হলো, এটি শর্ট সার্কিট কারেন্টকে তার সর্বোচ্চ বা পিক (Peak) মানে পৌঁছানোর আগেই (প্রথম এসি সাইকেলের ৪ ভাগের ১ ভাগের মধ্যে) সার্কিট কেটে দেয়। একে কারেন্ট লিমিটিং ক্ষমতা বলে। এর ফলে ডাউনস্ট্রিম ক্যাবল বা সুইচগিয়ারগুলো প্রচণ্ড যান্ত্রিক ও তাপীয় ধাক্কা থেকে রক্ষা পায়।"},{"title":"ব্রেকিং ক্যাপাসিটি বা রাপচারিং ক্ষমতা (Rupturing Capacity)","content":"একটি ফিউজ কোনো বিস্ফোরণ বা বডি ফেটে যাওয়া ছাড়াই সর্বোচ্চ যে পরিমাণ ফল্ট কারেন্ট নিরাপদে বন্ধ করতে পারে, তাকে তার ব্রেকিং ক্যাপাসিটি বলে। কিট-ক্যাট ফিউজের ব্রেকিং ক্যাপাসিটি খুবই কম (সাধারণত ৪-৮ kA), যেখানে HRC ফিউজের ব্রেকিং ক্যাপাসিটি অত্যন্ত বেশি (৮০ kA বা তার বেশি)। এই কারণেই আধুনিক সিস্টেমে HRC ফিউজ এত জনপ্রিয় ও নিরাপদ।"}]}}$json$::jsonb,
